-- A stable, evenly spread order for the homepage feature rotation: md5 of the
-- slug, so it never changes for a product and is independent of the
-- positional prod-N ids. Generated by the database; the sync never writes it.
alter table site_products
  add column if not exists sort_key text
  generated always as (md5(slug)) stored;

create index if not exists site_products_sort_key_idx
  on site_products (sort_key);
